// --- Error Handling ---

enum OperationType {
  CREATE = "create",
  UPDATE = "update",
  DELETE = "delete",
  LIST = "list",
  GET = "get",
  WRITE = "write",
}

function handleApiError(
  error: unknown,
  operationType: OperationType,
  path: string | null,
) {
  console.error(`API Error (${operationType}) on ${path}:`, error);
  alert(
    `Error en la operación ${operationType}: ${error instanceof Error ? error.message : String(error)}`,
  );
}

function invalidateApiCache() {
  try {
    Object.keys(sessionStorage).forEach((key) => {
      if (key.startsWith("api_cache_")) {
        sessionStorage.removeItem(key);
      }
    });
  } catch (e) {
    console.error("Error clearing api cache:", e);
  }
}

export function getDenominations(cashDenominationsStr?: string): number[] {
  if (!cashDenominationsStr) {
    return [200, 100, 50, 20, 10, 5, 2, 1, 0.5, 0.2, 0.1];
  }
  try {
    const parsed = JSON.parse(cashDenominationsStr);
    if (Array.isArray(parsed)) {
      return parsed
        .map(Number)
        .filter((n) => !isNaN(n) && n > 0)
        .sort((a, b) => b - a);
    }
  } catch (e) {
    const list = cashDenominationsStr
      .split(",")
      .map((s) => parseFloat(s.trim()))
      .filter((n) => !isNaN(n) && n > 0);
    if (list.length > 0) return list.sort((a, b) => b - a);
  }
  return [200, 100, 50, 20, 10, 5, 2, 1, 0.5, 0.2, 0.1];
}

const inflightRequests = new Map<string, Promise<any>>();

async function apiFetch(url: string, options?: RequestInit): Promise<any> {
  const method = options?.method || "GET";

  if (method === "GET") {
    const bypassCache =
      options?.headers && (options.headers as any)["X-Bypass-Cache"] === "true";
    if (!bypassCache) {
      const cached = sessionStorage.getItem(`api_cache_${url}`);
      const cachedTime = sessionStorage.getItem(`api_cache_time_${url}`);
      if (cached && cachedTime) {
        const age = Date.now() - parseInt(cachedTime, 10);
        // Cache TTL of 30 seconds to prevent rate limiting (HTTP 429) during parallel/consecutive fetches
        if (age < 30000) {
          try {
            return JSON.parse(cached);
          } catch (e) {
            // ignore and fetch fresh
          }
        }
      }

      // Check in-flight requests to deduplicate concurrent requests for the same URL
      if (inflightRequests.has(url)) {
        return inflightRequests.get(url)!;
      }
    }
  } else {
    invalidateApiCache();
  }

  // Strip our custom cache bypass header so the native fetch stays clean
  const cleanOptions = { ...options };
  const headersObj = { ...((cleanOptions.headers || {}) as any) };
  delete headersObj["X-Bypass-Cache"];
  cleanOptions.headers = headersObj;

  const fetchPromise = (async () => {
    let attempts = 0;
    const maxAttempts = 8;
    let delay = 1000;

    while (true) {
      try {
        const res = await fetch(url, { ...cleanOptions, cache: "no-store" });
        const text = await res.text();
        const trimmed = text.trim();

        if (
          res.status === 429 ||
          trimmed.startsWith("<") ||
          trimmed.toLowerCase().includes("<!doctype html>")
        ) {
          attempts++;
          if (attempts >= maxAttempts) {
            throw new Error(
              `HTTP 429 or HTML Fallback received from API. Rate exceeded or server unavailable (${url})`,
            );
          }
          console.warn(
            `[apiFetch] Rate limited (429) or HTML response on ${url}. Retrying in ${delay}ms... (attempt ${attempts}/${maxAttempts})`,
          );
          await new Promise((resolve) => setTimeout(resolve, delay));
          delay = Math.min(delay * 1.5, 3000); // Backoff capped at 3s
          continue;
        }

        if (!res.ok) {
          let errorMessage = `HTTP ${res.status}`;
          try {
            const json = JSON.parse(text);
            if (json.error) errorMessage = json.error;
            else if (json.message) errorMessage = json.message;
          } catch {
            errorMessage = `${errorMessage}: ${text.slice(0, 100)}`;
          }
          throw new Error(`${errorMessage} (${url})`);
        }

        const data = JSON.parse(text);
        if (method === "GET") {
          try {
            sessionStorage.setItem(`api_cache_${url}`, text);
            sessionStorage.setItem(
              `api_cache_time_${url}`,
              Date.now().toString(),
            );
          } catch (e) {
            console.warn("sessionStorage storage limit or access issue:", e);
          }
        }
        return data;
      } catch (err: any) {
        if (
          err.message &&
          (err.message.includes("HTTP 429") ||
            err.message.includes("HTML Fallback"))
        ) {
          throw err;
        }
        // For other potential transient network errors while fetching, retry up to maxAttempts
        attempts++;
        if (attempts >= maxAttempts) {
          throw err;
        }
        await new Promise((resolve) => setTimeout(resolve, delay));
        delay *= 2;
      } finally {
        if (method === "GET") {
          inflightRequests.delete(url);
        }
      }
    }
  })();

  if (method === "GET") {
    const bypassCache =
      options?.headers && (options.headers as any)["X-Bypass-Cache"] === "true";
    if (!bypassCache) {
      inflightRequests.set(url, fetchPromise);
    }
  }

  return fetchPromise;
}

