  const currentCycleMoves = useMemo(() => {
    if (!branchMode) return [];

    const latestClosure = [...branchClosures]
      .filter((c) => c.branchId === branchMode)
      .sort(
        (a, b) =>
          new Date(b.closedAt).getTime() - new Date(a.closedAt).getTime(),
      )[0];

    if (!latestClosure) return branchCashMoves;

    const closureDate = new Date(latestClosure.closedAt).getTime();
    return branchCashMoves.filter(
      (m) => new Date(m.date).getTime() > closureDate,
    );
  }, [branchCashMoves, branchClosures, branchMode]);

  const closureComplianceStats = useMemo(() => {
    if (!branchMode)
      return {
        daysSinceLastClosure: null,
        status: "unknown",
        text: "",
        protocolBreach: false,
        lastClosureDate: null,
      };

    const branchModeClosures = [...branchClosures]
      .filter((c) => c.branchId === branchMode)
      .sort(
        (a, b) =>
          new Date(b.closedAt || b.date).getTime() -
          new Date(a.closedAt || a.date).getTime(),
      );

    const lastClosure = branchModeClosures[0];

    if (!lastClosure) {
      return {
        daysSinceLastClosure: null,
        status: "no_records",
        text: "Sin registros de cierre",
        protocolBreach: true,
        lastClosureDate: null,
      };
    }

    const closureDateObj = new Date(lastClosure.closedAt || lastClosure.date);
    const todayDateObj = new Date();

    const d1 = Date.UTC(
      todayDateObj.getFullYear(),
      todayDateObj.getMonth(),
      todayDateObj.getDate(),
    );
    const d2 = Date.UTC(
      closureDateObj.getFullYear(),
      closureDateObj.getMonth(),
      closureDateObj.getDate(),
    );

    const diffMs = d1 - d2;
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    const finalDays = diffDays >= 0 ? diffDays : 0;

    let status: "compliant" | "warning" | "breach" = "compliant";
    let text = "";
    let protocolBreach = false;

    if (finalDays === 0) {
      status = "compliant";
      text = "Al día (Cierre realizado hoy)";
      protocolBreach = false;
    } else if (finalDays === 1) {
      status = "warning";
      text = "Pendiente (Último cierre fue ayer)";
      protocolBreach = false;
    } else {
      status = "breach";
      text = `Incumplimiento (${finalDays} días sin cerrar)`;
      protocolBreach = true;
    }

    return {
      daysSinceLastClosure: finalDays,
      status,
      text,
      protocolBreach,
      lastClosureDate: lastClosure.closedAt || lastClosure.date,
    };
  }, [branchClosures, branchMode]);

