  // Monitor inactivity to auto-lock (configurado de forma flexible)
  useEffect(() => {
    if (!user || isLocked) return;

    const handleInteraction = () => {
      lastActivityRef.current = Date.now();
    };

    window.addEventListener("mousemove", handleInteraction);
    window.addEventListener("keydown", handleInteraction);
    window.addEventListener("click", handleInteraction);
    window.addEventListener("scroll", handleInteraction);
    window.addEventListener("touchstart", handleInteraction);

    const interval = setInterval(() => {
      const inactiveMs = Date.now() - lastActivityRef.current;
      const timeoutVal = companySettings?.inactivityTimeout;
      const minutes =
        typeof timeoutVal === "number"
          ? timeoutVal
          : timeoutVal
            ? parseInt(timeoutVal, 10)
            : 10;
      const LIMIT = (isNaN(minutes) || minutes <= 0 ? 10 : minutes) * 60 * 1000;
      if (inactiveMs >= LIMIT) {
        setIsLocked(true);
        localStorage.setItem("aurum_locked", "true");
      }
    }, 5000);

    return () => {
      window.removeEventListener("mousemove", handleInteraction);
      window.removeEventListener("keydown", handleInteraction);
      window.removeEventListener("click", handleInteraction);
      window.removeEventListener("scroll", handleInteraction);
      window.removeEventListener("touchstart", handleInteraction);
      clearInterval(interval);
    };
  }, [user, isLocked, companySettings]);

