  const handlePerformToggleHistoric = async () => {
    if (!historicTargetPurchase || !historicValidator.trim() || !user) {
      alert("Por favor cargue un validador/auditor válido.");
      return;
    }

    setIsTogglingHistoric(true);
    try {
      const isCurrentlyHistoric =
        historicTargetPurchase.isHistoric === 1 ||
        historicTargetPurchase.isHistoric === true ||
        parseInt(historicTargetPurchase.isHistoric + "") === 1;
      const targetStateLabel = isCurrentlyHistoric ? "Normal" : "Histórico";

      await apiFetch(
        `/api/gold-purchases/${historicTargetPurchase.id}/toggle-historic`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            validatedBy: `${historicValidator.trim()} (Auditor/Validador)`,
            reason: historicReason.trim(),
          }),
        },
      );

      await fetchData(true);

      // Add a nice toast if allowed, or standard alert
      alert(
        `La compra #${historicTargetPurchase.receiptNumber} ha cambiado de tipo con éxito. Estado actual: ${targetStateLabel}. Caja chica y materiales ajustados correctamente.`,
      );

      setShowToggleHistoricModal(false);
      setHistoricTargetPurchase(null);
      setHistoricValidator("");
      setHistoricReason("");
    } catch (error) {
      handleApiError(
        error,
        OperationType.UPDATE,
        `gold-purchases/${historicTargetPurchase.id}/toggle-historic`,
      );
    } finally {
      setIsTogglingHistoric(false);
    }
  };

  const handlePrintAdvanceReceipt = (
    purchase: GoldPurchase | null,
    specificAdvance?: AdvancePayment,
  ) => {
    if (!purchase) return;

    const amount = Math.floor(
      specificAdvance ? specificAdvance.amount : purchase.advancePayment || 0,
    );
    if (amount <= 0 && !specificAdvance) return;

    // Si es tipo cerrado o es pago total, el concepto cambia
    const isFull = purchase.isFullPayment || purchase.type === "cerrado";
    const title = specificAdvance
      ? "COMPROBANTE DE ADELANTO"
      : isFull
        ? "COMPROBANTE DE PAGO (100%)"
        : "COMPROBANTE DE ADELANTO";
    const concept = specificAdvance
      ? specificAdvance.concept
      : isFull
        ? `Pago total (100%) correspondiente a la Compra de Oro #${purchase.receiptNumber}`
        : `Adelanto correspondiente a la Compra de Oro #${purchase.receiptNumber}`;

    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a5",
    });

    const company = companySettings;
    const branch = branches.find((b) => b.id === purchase.branchId);
    const client = clients.find((c) => c.id === purchase.clientId);
    const creatorUser = systemUsers.find(
      (u) =>
        u.id === purchase.createdBy ||
        u.username === purchase.createdBy ||
        u.email === purchase.createdBy,
    );

    const margin = 15;
    const pageWidth = 148;
    const contentWidth = pageWidth - margin * 2;

    // Header Borders
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.5);
    doc.line(margin, 10, pageWidth - margin, 10); // Top line

    // Header - Company Info
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text(company?.name?.toUpperCase() || "AURUM MANAGER", margin, 18);

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(company?.address || "", margin, 23);
    doc.text(
      `Tel: ${company?.phone || ""} | NIT: ${company?.taxId || ""}`,
      margin,
      27,
    );
    doc.text(`Email: ${company?.email || ""}`, margin, 31);

    // Branch/Payment Info (Top Right)
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text(title, pageWidth - margin, 18, { align: "right" });
    doc.setFontSize(12);
    doc.setTextColor(180, 0, 0);
    doc.text(`PAG-${purchase.receiptNumber}`, pageWidth - margin, 24, {
      align: "right",
    });

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(`Sucursal: ${branch?.name || "Central"}`, pageWidth - margin, 31, {
      align: "right",
    });

    doc.line(margin, 35, pageWidth - margin, 35); // Divider

    // Date and Operator Info
    const registerDate = new Date(purchase.createdAt);
    doc.setFontSize(8);
    doc.setTextColor(80, 80, 80);
    doc.text(
      `Fecha/Hora: ${registerDate.toLocaleDateString()} ${registerDate.toLocaleTimeString()}`,
      margin,
      42,
    );
    doc.setFont("helvetica", "bold");
    doc.text(
      `Usuario que registró: ${creatorUser?.name || purchase.createdBy || "Sistema"}`,
      pageWidth - margin,
      42,
      { align: "right" },
    );

    // Client Info Section
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("DATOS DEL CLIENTE", margin, 52);

    doc.setLineWidth(0.1);
    doc.setDrawColor(200, 200, 200);
    doc.rect(margin, 55, contentWidth, 20); // Border around client info

    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text(`Señor(es): ${client?.name || "Desconocido"}`, margin + 5, 62);
    doc.text(`C.I. / NIT: ${client?.ci || "S/N"}`, margin + 5, 68);
    doc.text(
      `Fecha: ${new Date().toLocaleDateString()}`,
      pageWidth - margin - 35,
      68,
    );

    // Details table
    autoTable(doc, {
      startY: 80,
      margin: { left: margin, right: margin },
      head: [["Descripción del Concepto", "Importe (BS)"]],
      body: [[concept, formatNumber(amount)]],
      theme: "grid",
      headStyles: {
        fillColor: [240, 240, 240],
        textColor: 0,
        fontStyle: "bold",
        lineWidth: 0.1,
        lineColor: [0, 0, 0],
      },
      styles: {
        fontSize: 10,
        cellPadding: 4,
        lineColor: [0, 0, 0],
        lineWidth: 0.1,
      },
      columnStyles: {
        1: { halign: "right", fontStyle: "bold" },
      },
    });

    const finalY = (doc as any).lastAutoTable.finalY + 8;

    // Amount in Literal
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text("SON:", margin, finalY);
    doc.setFont("helvetica", "normal");
    const literal = numeroALetras(amount);
    // Wrap text if literal is too long
    const splitLiteral = doc.splitTextToSize(literal, contentWidth - 15);
    doc.text(splitLiteral, margin + 12, finalY);

    const literalHeight = splitLiteral.length * 4;
    const totalY = finalY + literalHeight + 5;

    // Total highlight
    const totalBoxWidth = 65;
    doc.setLineWidth(0.5);
    doc.line(
      pageWidth - margin - totalBoxWidth,
      totalY - 4,
      pageWidth - margin,
      totalY - 4,
    );

    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    const footerTotalLabel = isFull ? "TOTAL PAGADO:" : "TOTAL RECIBIDO:";
    doc.text(footerTotalLabel, pageWidth - margin - totalBoxWidth, totalY + 2);

    doc.setFontSize(12);
    doc.text(`${formatNumber(amount)} BS`, pageWidth - margin, totalY + 2, {
      align: "right",
    });

    doc.setLineWidth(0.5);
    doc.line(
      pageWidth - margin - totalBoxWidth,
      totalY + 5,
      pageWidth - margin,
      totalY + 5,
    );

    // Bank Details if transfer or mixed
    if (
      purchase.advancePaymentType === "transferencia" ||
      purchase.advancePaymentType === "mixto"
    ) {
      const sourceBank = branchBankAccounts.find(
        (acc) => acc.id === purchase.advanceSourceBankAccountId,
      );
      doc.setFontSize(8);
      doc.setFont("helvetica", "bold");
      doc.text("DETALLES DE PAGO BANCARIO:", margin, totalY + 12);
      doc.setFont("helvetica", "normal");
      if (purchase.advancePaymentType === "mixto") {
        doc.text(
          `Desglosé: Efectivo: ${formatNumber(purchase.advanceCashAmount || 0)} BS | Banco: ${formatNumber(purchase.advanceBankAmount || 0)} BS`,
          margin,
          totalY + 16,
        );
      }
      doc.text(
        `Origen (Sucursal): ${sourceBank ? `${sourceBank.bankName} - ${sourceBank.accountNumber}` : "Transferencia Bancaria"}`,
        margin,
        totalY + (purchase.advancePaymentType === "mixto" ? 20 : 16),
      );
      doc.text(
        `Destino (Cliente): ${purchase.advanceClientBank || ""} - ${purchase.advanceClientAccountNumber || ""}`,
        margin,
        totalY + (purchase.advancePaymentType === "mixto" ? 24 : 20),
      );
    }

    // Signatures
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");

    const signY = 185;
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.2);

    doc.line(margin + 5, signY, margin + 45, signY);
    doc.text("ENTREGADO POR", margin + 25, signY + 5, { align: "center" });
    doc.setFontSize(7);
    doc.text(creatorUser?.name || "", margin + 25, signY + 9, {
      align: "center",
    });

    doc.setFontSize(8);
    doc.line(pageWidth - margin - 45, signY, pageWidth - margin - 5, signY);
    doc.text("RECIBIDO POR (CLIENTE)", pageWidth - margin - 25, signY + 5, {
      align: "center",
    });

    // Global Border
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.2);
    doc.rect(5, 5, pageWidth - 10, 200);

    doc.save(
      `${isFull ? "Recibo_Pago" : "Recibo_Adelanto"}_${purchase.receiptNumber}.pdf`,
    );
  };

  const handlePrintLiquidationReceipt = (purchase: GoldPurchase | null) => {
    if (!purchase) return;

    // Determines if it is a direct closed purchase (no recalculation closure total)
    const isDirectClosed = !purchase.closeTotal || purchase.closeTotal <= 0;

    let finalTotal = 0;
    let totalAllAdvances = 0;
    let amount = 0;
    let closedAtDateString = "";
    let closedByUsername = "";
    let conceptDescription = "";

    let paymentType = "efectivo";
    let cashAmount = 0;
    let bankAmount = 0;
    let sourceBankAccountId = "";
    let clientBank = "";
    let clientAccountNumber = "";

    if (isDirectClosed) {
      finalTotal = purchase.total;
      totalAllAdvances = 0;
      amount = purchase.total;
      closedAtDateString = purchase.createdAt;
      closedByUsername = purchase.createdBy;
      conceptDescription = `Pago total (100%) correspondiente a la Compra de Oro Directa Cerrada #${purchase.receiptNumber}.`;

      paymentType = purchase.advancePaymentType || "efectivo";
      cashAmount = purchase.advanceCashAmount || 0;
      bankAmount = purchase.advanceBankAmount || 0;
      sourceBankAccountId = purchase.advanceSourceBankAccountId || "";
      clientBank = purchase.advanceClientBank || "";
      clientAccountNumber = purchase.advanceClientAccountNumber || "";
    } else {
      const totalExtraAdvances =
        purchase.advances?.reduce((sum, adv) => sum + adv.amount, 0) || 0;
      totalAllAdvances = (purchase.advancePayment || 0) + totalExtraAdvances;
      finalTotal = purchase.closeTotal || purchase.total;
      amount = parseFloat((finalTotal - totalAllAdvances).toFixed(2));
      closedAtDateString = purchase.closedAt || purchase.createdAt;
      closedByUsername = purchase.closedBy || purchase.createdBy;
      conceptDescription = `Liquidación final de saldo correspondiente a la Compra de Oro Cerrada #${purchase.receiptNumber}. Detalle de Cierre a Cotización. Factor de Apertura: ${purchase.openEstimateFactor !== undefined ? purchase.openEstimateFactor : 90}%.`;

      paymentType = purchase.closePaymentType || "efectivo";
      cashAmount = purchase.closeCashAmount || 0;
      bankAmount = purchase.closeBankAmount || 0;
      sourceBankAccountId = purchase.closeSourceBankAccountId || "";
      clientBank = purchase.closeClientBank || "";
      clientAccountNumber = purchase.closeClientAccountNumber || "";
    }

    if (amount <= 0 && !isDirectClosed) {
      alert(
        "No hay un saldo pendiente a pagar para esta liquidación (el total de adelantos cubre el total de cierre).",
      );
      return;
    }

    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a5",
    });

    const company = companySettings;
    const branch = branches.find((b) => b.id === purchase.branchId);
    const client = clients.find((c) => c.id === purchase.clientId);
    const closedDate = new Date(closedAtDateString);
    const opUser = systemUsers.find(
      (u) =>
        u.id === closedByUsername ||
        u.username === closedByUsername ||
        u.email === closedByUsername,
    );

    const margin = 15;
    const pageWidth = 148;
    const contentWidth = pageWidth - margin * 2;

    // Header Borders
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.5);
    doc.line(margin, 10, pageWidth - margin, 10); // Top line

    // Header - Company Info
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text(company?.name?.toUpperCase() || "AURUM MANAGER", margin, 18);

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(company?.address || "", margin, 23);
    doc.text(
      `Tel: ${company?.phone || ""} | NIT: ${company?.taxId || ""}`,
      margin,
      27,
    );
    doc.text(`Email: ${company?.email || ""}`, margin, 31);

    // Branch/Payment Info (Top Right)
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    const documentTitle = isDirectClosed
      ? "COMPROBANTE DE COMPRA (PAGO 100%)"
      : "COMPROBANTE DE CIERRE - LIQUIDACIÓN";
    doc.text(documentTitle, pageWidth - margin, 18, { align: "right" });
    doc.setFontSize(12);
    doc.setTextColor(0, 100, 0);
    const receiptCode = isDirectClosed
      ? purchase.receiptNumber
      : `LIQ-${purchase.receiptNumber}`;
    doc.text(receiptCode, pageWidth - margin, 24, { align: "right" });

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(`Sucursal: ${branch?.name || "Central"}`, pageWidth - margin, 31, {
      align: "right",
    });

    doc.line(margin, 35, pageWidth - margin, 35); // Divider

    // Date and Operator Info
    doc.setFontSize(8);
    doc.setTextColor(80, 80, 80);
    doc.text(
      `Fecha Emisión: ${closedDate.toLocaleDateString()} ${closedDate.toLocaleTimeString()}`,
      margin,
      42,
    );
    doc.setFont("helvetica", "bold");
    doc.text(
      `Usuario: ${opUser?.name || closedByUsername || "Sistema"}`,
      pageWidth - margin,
      42,
      { align: "right" },
    );

    // Client Info Section
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("DATOS DEL CLIENTE", margin, 52);

    doc.setLineWidth(0.1);
    doc.setDrawColor(200, 200, 200);
    doc.rect(margin, 55, contentWidth, 20); // Border around client info

    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text(`Señor(es): ${client?.name || "Desconocido"}`, margin + 5, 62);
    doc.text(`C.I. / NIT: ${client?.ci || "S/N"}`, margin + 5, 68);
    doc.text(
      `Fecha Pago: ${closedDate.toLocaleDateString()}`,
      pageWidth - margin - 45,
      68,
    );

    // Details table
    autoTable(doc, {
      startY: 80,
      margin: { left: margin, right: margin },
      head: [["Descripción del Concepto", "Importe (BS)"]],
      body: [[conceptDescription, formatNumber(amount)]],
      theme: "grid",
      headStyles: {
        fillColor: [240, 240, 240],
        textColor: 0,
        fontStyle: "bold",
        lineWidth: 0.1,
        lineColor: [0, 0, 0],
      },
      styles: {
        fontSize: 10,
        cellPadding: 4,
        lineColor: [0, 0, 0],
        lineWidth: 0.1,
      },
      columnStyles: {
        1: { halign: "right", fontStyle: "bold" },
      },
    });

    const finalY = (doc as any).lastAutoTable.finalY + 8;

    // Amount in Literal
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text("SON:", margin, finalY);
    doc.setFont("helvetica", "normal");
    const literal = numeroALetras(amount);
    // Wrap text if literal is too long
    const splitLiteral = doc.splitTextToSize(literal, contentWidth - 15);
    doc.text(splitLiteral, margin + 12, finalY);

    const literalHeight = splitLiteral.length * 4;
    const totalY = finalY + literalHeight + 5;

    // Total highlight block based on the situation
    if (isDirectClosed) {
      const totalBoxWidth = 65;
      doc.setLineWidth(0.5);
      doc.line(
        pageWidth - margin - totalBoxWidth,
        totalY - 4,
        pageWidth - margin,
        totalY - 4,
      );

      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(0, 100, 0);
      doc.text(
        "LIQUIDACIÓN PAGADA:",
        pageWidth - margin - totalBoxWidth,
        totalY + 2,
      );
      doc.setFontSize(11);
      doc.text(
        `${formatNumber(finalTotal)} BS`,
        pageWidth - margin,
        totalY + 2,
        { align: "right" },
      );
    } else {
      const totalBoxWidth = 65;
      doc.setLineWidth(0.5);
      doc.line(
        pageWidth - margin - totalBoxWidth,
        totalY - 4,
        pageWidth - margin,
        totalY - 4,
      );

      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.text(
        "TOTAL RECALCULADO:",
        pageWidth - margin - totalBoxWidth,
        totalY + 2,
      );
      doc.setFontSize(10);
      doc.text(
        `${formatNumber(finalTotal)} BS`,
        pageWidth - margin,
        totalY + 2,
        { align: "right" },
      );

      const secondTotalY = totalY + 6;
      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.text(
        "(-) ADELANTOS PREVIOS:",
        pageWidth - margin - totalBoxWidth,
        secondTotalY + 2,
      );
      doc.setFontSize(10);
      doc.text(
        `${formatNumber(totalAllAdvances)} BS`,
        pageWidth - margin,
        secondTotalY + 2,
        { align: "right" },
      );

      const thirdTotalY = secondTotalY + 6;
      doc.line(
        pageWidth - margin - totalBoxWidth,
        thirdTotalY - 1,
        pageWidth - margin,
        thirdTotalY - 1,
      );

      doc.setFontSize(10);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(0, 100, 0);
      doc.text(
        "LIQUIDACIÓN PAGADA:",
        pageWidth - margin - totalBoxWidth,
        thirdTotalY + 2,
      );
      doc.setFontSize(11);
      doc.text(
        `${formatNumber(amount)} BS`,
        pageWidth - margin,
        thirdTotalY + 2,
        { align: "right" },
      );
    }

    let runningY = (isDirectClosed ? totalY : totalY + 12) + 8;

    // Bank Details if transfer or mixed
    if (paymentType === "transferencia" || paymentType === "mixto") {
      const sourceBank = branchBankAccounts.find(
        (acc) => acc.id === sourceBankAccountId,
      );
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(8);
      doc.setFont("helvetica", "bold");
      doc.text("DETALLES DE PAGO BANCARIO:", margin, runningY);
      doc.setFont("helvetica", "normal");
      runningY += 4;
      if (paymentType === "mixto") {
        doc.text(
          `Desglose: Efectivo: ${formatNumber(cashAmount || 0)} BS | Banco: ${formatNumber(bankAmount || 0)} BS`,
          margin,
          runningY,
        );
        runningY += 4;
      }
      doc.text(
        `Origen (Sucursal): ${sourceBank ? `${sourceBank.bankName} - ${sourceBank.accountNumber}` : "Transferencia Bancaria"}`,
        margin,
        runningY,
      );
      runningY += 4;
      doc.text(
        `Destino (Cliente): ${clientBank || ""} - ${clientAccountNumber || ""}`,
        margin,
        runningY,
      );
    }

    // Signatures Area
    const finalSignY = 185;
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(8);
    doc.setLineWidth(0.2);
    doc.setDrawColor(0, 0, 0);

    if (purchase.closeSignature) {
      try {
        doc.addImage(
          purchase.closeSignature,
          "PNG",
          margin + 10,
          finalSignY - 18,
          30,
          15,
        );
      } catch (e) {
        console.error("Error rendering signature on PDF:", e);
      }
    }
    doc.line(margin + 5, finalSignY, margin + 45, finalSignY);
    doc.text("RECIBÍ CONFORME", margin + 25, finalSignY + 5, {
      align: "center",
    });

    doc.setFontSize(8);
    doc.line(
      pageWidth - margin - 45,
      finalSignY,
      pageWidth - margin - 5,
      finalSignY,
    );
    doc.text("RESPONSABLE CAJA", pageWidth - margin - 25, finalSignY + 5, {
      align: "center",
    });
    doc.setFontSize(7);
    doc.text(
      opUser?.name || closedByUsername || "Sistema",
      pageWidth - margin - 25,
      finalSignY + 9,
      { align: "center" },
    );

    // Global Border
    doc.rect(5, 5, pageWidth - 10, 200);

    doc.save(`LIQUIDACION_Saldo_${purchase.receiptNumber}.pdf`);
  };

