                  const overallPurchasesSum = clientPurchases.reduce(
                    (sum, p) =>
                      sum +
                      (p.type === "cerrado"
                        ? p.closeTotal || p.total
                        : p.total),
                    0,
                  );
                  const overallAdvancesSum = clientPurchases.reduce(
                    (sum, p) => {
                      if (p.type === "cerrado") {
                        return sum + (p.closeTotal || p.total);
                      } else {
                        return (
                          sum +
                          (p.advancePayment || 0) +
                          (p.advances?.reduce(
                            (advSum, a) => advSum + a.amount,
                            0,
                          ) || 0)
                        );
                      }
                    },
                    0,
                  );
